            background-color: #fff;
            margin: 0;
            margin-top: 0.125rem;
            font: inherit;
            color: currentColor;
            width: 1.25em;
            height: 1.25em;
            border: 2px solid var(--border-color);
            border-radius: 0.25em;
            display: grid;
            place-content: center;
