<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState } = React;

        const questions = [
            {
                id: "q1",
                legend: "1. Which of the following are object-oriented programming languages?",
                helpText: "Select all that apply.",
                options: [
                    { value: "java", label: "Java" },
                    { value: "cpp", label: "C++" },
                    { value: "python", label: "Python" },
                    { value: "html", label: "HTML" }
                ]
            },
            {
                id: "q2",
                legend: "2. Which of these languages are primarily used for web frontend development?",
                helpText: null,
                options: [
                    { value: "javascript", label: "JavaScript" },
                    { value: "typescript", label: "TypeScript" },
                    { value: "sql", label: "SQL" },
                    { value: "rust", label: "Rust" }
                ]
            },
            {
                id: "q3",
                legend: "3. Which of the following are typically compiled languages?",
                helpText: null,
                options: [
                    { value: "c", label: "C" },
                    { value: "go", label: "Go" },
                    { value: "rust", label: "Rust" },
                    { value: "python", label: "Python" }
                ]
            }
        ];

        function CheckboxGroup({ question, answers, onChange }) {
            const { id, legend, helpText, options } = question;
            const helpTextId = helpText ? `${id}-help` : undefined;

            return (
                <div className="form-field">
                    <fieldset aria-describedby={helpTextId}>
                        <legend>{legend}</legend>
                        {helpText && (
                            <p id={helpTextId} className="help-text">{helpText}</p>
                        )}
                        <div className="checkbox-container">
                            {options.map(option => {
                                const checkboxId = `${id}-${option.value}`;
                                const isChecked = answers[id]?.includes(option.value) || false;
                                return (
                                    <div key={option.value} className="checkbox-option">
                                        <input
                                            type="checkbox"
                                            id={checkboxId}
                                            name={id}
                                            value={option.value}
                                            checked={isChecked}
                                            onChange={(e) => {
                                                const checked = e.target.checked;
                                                const currentAnswers = answers[id] || [];
                                                let newAnswers;
                                                if (checked) {
                                                    newAnswers = [...currentAnswers, option.value];
                                                } else {
                                                    newAnswers = currentAnswers.filter(val => val !== option.value);
                                                }
                                                onChange(id, newAnswers);
                                            }}
                                        />
                                        <label htmlFor={checkboxId}>{option.label}</label>
                                    </div>
                                );
                            })}
                        </div>
                    </fieldset>
                </div>
            );
        }

        function QuizApp() {
            const [answers, setAnswers] = useState({});
            const [submitted, setSubmitted] = useState(false);

            const handleAnswerChange = (questionId, newAnswers) => {
                setAnswers(prev => ({
                    ...prev,
                    [questionId]: newAnswers
                }));
            };

            const handleSubmit = (e) => {
                e.preventDefault();
                setSubmitted(true);
            };

            return (
                <main>
                    <h1>Computer Languages Quiz</h1>
                    <form onSubmit={handleSubmit}>
                        {questions.map(q => (
                            <CheckboxGroup
                                key={q.id}
                                question={q}
                                answers={answers}
                                onChange={handleAnswerChange}
                            />
                        ))}
                        <button type="submit">Submit Quiz</button>
                    </form>

                    {submitted && (
                        <div className="status-message success" role="status" aria-live="polite">
                            Quiz submitted successfully!
                        </div>
                    )}
                </main>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<QuizApp />);
    </script>
</body>
